mapper.insert:
insert into orders (
    number, status, user_id, address_book_id, order_time, pay_method, pay_status, amount
    , checkout_time
    , remark
    , phone
    , address
    , user_name
    , consignee
    , estimated_ship_time
    , shipping_status
    , freight_amount
    , invoice_type
    , invoice_title
)
values (
    #{number}, #{status}, #{userId}, #{addressBookId}, #{orderTime}, #{payMethod}, #{payStatus}, #{amount}
    , #{checkoutTime}
    , #{remark}
    , #{phone}
    , #{address}
    , #{userName}
    , #{consignee}
    , #{estimatedShipTime}
    , #{shippingStatus}
    , #{freightAmount}
    , #{invoiceType}
    , #{invoiceTitle}
)

mapper.select:
select * from orders


        and number like concat('%',#{number},'%')


        and (number like concat('%',#{keyword},'%') or exists (
            select 1 from order_detail od
            where od.order_id = orders.id and od.name like concat('%',#{keyword},'%')
        ))


        and phone like concat('%',#{phone},'%')


        and user_id = #{userId}


        and status = #{status}


        and status in

            #{item}



        and refund_status = #{refundStatus}


        and refund_status in

            #{item}



        and (refund_status is null or refund_status not in (1, 2, 3, 4))


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc
